def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    count_exceeding = sum(value > 200 for value in (v1, v2))

    return {
        "value": count_exceeding,
        "trace": {
            "threshold": 200,
            "qualifying_values": [value for value in (v1, v2) if value > 200],
            "count_exceeding": count_exceeding,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "count"
            }
        }
    }
